<?php
declare(strict_types=1);
require_once __DIR__.'/../../../src/config.php'; require_once __DIR__.'/../../../src/db.php'; header('Content-Type: application/json; charset=utf-8');
$key=$_SERVER['HTTP_X_API_KEY']??''; if(!hash_equals((string)env('N8N_API_KEY'),(string)$key)){http_response_code(401);echo json_encode(['error'=>'unauthorized']);exit;}
$d=json_decode(file_get_contents('php://input')?:'{}',true);
try{$sid=(string)($d['student_id']??'');$items=$d['corrections']??[];if($sid===''||!is_array($items))throw new RuntimeException('Payload inválido.');$s=db()->prepare("INSERT INTO correction_events(student_id,session_id,channel,correction_type,original_text,corrected_text,explanation,target_word,detected_word,confidence_score,accepted) VALUES(:student_id,:session_id,:channel,:correction_type,:original_text,:corrected_text,:explanation,:target_word,:detected_word,:confidence_score,:accepted)");$c=0;foreach($items as $i){if(!is_array($i))continue;$s->execute(['student_id'=>$sid,'session_id'=>$d['session_id']??null,'channel'=>$d['channel']??'unknown','correction_type'=>$i['correction_type']??'written','original_text'=>$i['original_text']??null,'corrected_text'=>$i['corrected_text']??null,'explanation'=>$i['explanation']??null,'target_word'=>$i['target_word']??null,'detected_word'=>$i['detected_word']??null,'confidence_score'=>$i['confidence_score']??null,'accepted'=>array_key_exists('accepted',$i)?(bool)$i['accepted']:true]);$c++;}echo json_encode(['ok'=>true,'saved'=>$c]);}catch(Throwable $e){http_response_code(500);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
